 */
CG3_INLINE AABBTree3::AABBTree3(const SimpleEigenMesh& m, bool forDistanceQueries)
{
    treeType = EIGENMESH;
    for (unsigned int i = 0; i < m.numberVertices(); i++){
        Point3d p = m.vertex(i);
