            CGALTriangle tr(mapIdVerticesToCgalPoints.at(i1), mapIdVerticesToCgalPoints.at(i2), mapIdVerticesToCgalPoints.at(i3));
            mapCgalTrianglesToIdTriangles[tr] = i;
            triangles.push_back(tr);
