    return output;
}

CG3_INLINE void AABBTree3::intersectedDcelFaces(
        const Point3d& p1,
        const Point3d& p2,
        std::list<const Dcel::Face*>& outputList) const
{
    assert(treeType == DCEL);
    outputList.clear();
    CGALPoint pa(p1.x(), p1.y(), p1.z());
    CGALPoint pb(p2.x(), p2.y(), p2.z());
