{
    serializeObjectAttributes("cg3Plane", binaryFile, _normal, _d);
}

CG3_INLINE void Plane::deserialize(std::ifstream& binaryFile)
{
    deserializeObjectAttributes("cg3Plane", binaryFile, _normal, _d);
}

