CG3_INLINE Plane::Plane(const Point3d& p1, const Point3d& p2, const Point3d& p3)
{
    Vec3d v1 (p2 - p1);
    Vec3d v2 (p3 - p1);
    _normal = v1.cross(v2);
    _normal.normalize();
    _d = -(_normal.x() * p1.x() + _normal.y() * p1.y() + _normal.z() * p1.z());
}

CG3_INLINE double Plane::a() const
