    q[1] = -q[1];
    q[2] = -q[2];
}

CG3_INLINE void Quaternion::negate()
{
    invert();
    q[3] = -q[3];
}

CG3_INLINE double Quaternion::normalize()
{
    double norm = std::sqrt(q[0]*q[0] + q[1]*q[1] + q[2]*q[2] + q[3]*q[3]);
    for (unsigned int i = 0; i < 4; i++)
        q[i] /= norm;
    return norm;
}

