    bb(bbInitializer(bb)),
    container(this->bb.minX(), this->bb.maxX(),
              this->bb.minY(), this->bb.maxY(),
              this->bb.minZ(), this->bb.maxZ(),
              6, 6, 6, false, false, false,
              nPoints + 2),
    nPoints(nPoints+2)
{
}

