        intersectionPoint = a;
        code = 'v';
        return;
    }
    else if (cg3::epsilonEqual(b, d, eps) || cg3::epsilonEqual(c, b, eps))
    {
        intersectionPoint = b;
        code = 'v';
        return;
    }

    denom =
            a.x() * ( d.y() - c.y() ) +
            b.x() * ( c.y() - d.y() ) +
            d.x() * ( b.y() - a.y() ) +
